from pathlib import Path
from unittest.mock import patch

from batch_sync.dispatcher import dispatch_batch

class Response:
    def __init__(self, status_code, headers=None):
        self.status_code = status_code
        self.headers = headers or {}

calls = {}

def fake_post(url, json=None, timeout=None):
    event_id = json.get('event_id')
    calls[event_id] = calls.get(event_id, 0) + 1
    if event_id == 'retry' and calls[event_id] == 1:
        return Response(429, {'Retry-After': '0'})
    if event_id == 'fail':
        return Response(500)
    return Response(200)

summary_file = Path(tempfile.gettempdir()) / 'batch_sync_smoke_summary.json'
with patch('batch_sync.dispatcher.requests.post', side_effect=fake_post):
    summary = dispatch_batch(
        [{'event_id': 'ok'}, {'event_id': 'retry'}, {'event_id': 'fail'}],
        max_concurrency=2,
        summary_path=str(summary_file),
    )

print(summary)
